export default {
  html: "<h1 class=\"text-[14pt] font-bold mb-4 text-cyan-400 tracking-tighter leading-tight\">⟁ The underground thermodynamicists of mind, structure &amp; governance</h1>\n<blockquote class=\"border-l-2 border-cyan-500/50 pl-4 mb-6 text-cyan-400/70 italic\"><p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">A hidden network of thinkers has been building exactly the framework you describe</strong> — thermodynamic ontology applied to cognition, governance, and system design — scattered across forgotten books, marginal journals, self-published blogs, and institutional peripheries. These figures treat entropy, dissipation, and phase transitions not as metaphors but as <strong class=\"text-cyan-300 font-bold\">literal structural forces</strong> in cognition and social organization. Most were rejected, ignored, or sidelined precisely because they refused to keep physics in its lane.</p>\n</blockquote>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">◈ Signal map</h2>\n<table class=\"w-full mb-6 border-collapse border border-cyan-900/30\"><thead><tr><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">#</th><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Name</th><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Core axis</th><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Obscurity floor</th></tr></thead><tbody><tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">1</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Rod Swenson</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Thermodynamic cognition / fourth law</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">2</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Jeffrey S. Wicken</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Dissipative ontology</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">█████ Buried</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">3</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Gordon Pask</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Neuroarchitecture / self-growing machines</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">4</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Giuseppe Vitiello</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Dissipative quantum brain</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">5</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">François Roddier</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Thermodynamic economics</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">█████ Buried</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">6</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Diederik Aerts</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Quantum particles as concepts</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">7</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Stanley Salthe</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Second Law as cosmic final cause</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">8</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Yukio-Pegio Gunji</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Quantum logic from slime mould</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">█████ Buried</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">9</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Crispin Sartwell</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Formal anti-sycophancy</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">10</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Koichiro Matsuno</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Biology grounds physics</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">█████ Buried</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">11</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Timothy Garrett</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Wealth is literally energy</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">████░ Fringe</td></tr></tbody></table>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 01 — Rod Swenson</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">The fourth law that derives mind from entropy</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Active ~1988–present · CESPA Fellow, University of Connecticut · Former DARPA Physical Intelligence consultant</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Swenson may be the single closest match to the target profile. He proposed the <strong class=\"text-cyan-300 font-bold\">Law of Maximum Entropy Production (LMEP)</strong> — effectively a &quot;fourth law of thermodynamics&quot; — stating that the world acts to produce entropy at the maximum rate given constraints. The radical consequence: <strong class=\"text-cyan-300 font-bold\">order is not opposed to entropy but is the mechanism by which entropy production is maximized.</strong> Organisms, minds, and societies exist because structured dissipation produces entropy faster than disordered flows can.</p>\n<blockquote class=\"border-l-2 border-cyan-500/50 pl-4 mb-6 text-cyan-400/70 italic\"><p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><em class=\"text-fuchsia-300 italic\">&quot;The world is in the order-production business.&quot;</em></p>\n</blockquote>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">From this single principle, Swenson derives cognition directly. His 1991 paper with Michael Turvey argues that perception, action, and learning follow opportunistically from universal physical law. This is not analogy — <strong class=\"text-cyan-300 font-bold\">cognition is a thermodynamic process, full stop.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His concept of <strong class=\"text-cyan-300 font-bold\">autocatakinetic systems</strong> — self-organizing structures defined by circular thermodynamic causality — maps directly onto the TRANSMUTE principle. Spontaneous ordering is literally a micro-to-macro transformation where disordered microstates are selected into ordered macrostates because doing so accelerates entropy production.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Despite a 2023 Royal Society publication, Swenson has never held a conventional tenure-track position. His claim to a fourth thermodynamic law is considered overreach by mainstream physicists. Operates through his own Sonoran Institute for Epistemic Studies. Virtually unknown in mainstream philosophy of mind.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>uconn.academia.edu/RodSwenson</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;A Grand Unified Theory for the Unification of Physics, Life, Information and Cognition&quot; — <em class=\"text-fuchsia-300 italic\">Phil. Trans. Royal Society A</em> (2023, open access via PMC)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Autocatakinetics, Evolution, and the Law of Maximum Entropy Production&quot; — <em class=\"text-fuchsia-300 italic\">Advances in Human Ecology</em> 6, 1997</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Thermodynamic Reasons for Perception-Action Cycles&quot; — <em class=\"text-fuchsia-300 italic\">Ecological Psychology</em> 3(4), 1991</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 02 — Jeffrey S. Wicken</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">The forgotten architect of dissipative ontology</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ 1942–2002 · Biochemist, Penn State Erie Behrend College (branch campus, no graduate program)</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Wicken&#39;s central thesis is a single sentence that could serve as a manifesto:</p>\n<blockquote class=\"border-l-2 border-cyan-500/50 pl-4 mb-6 text-cyan-400/70 italic\"><p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><em class=\"text-fuchsia-300 italic\">&quot;Dissipation through structuring is the strategy of life.&quot;</em></p>\n</blockquote>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Organisms are &quot;informed kinetic structures&quot; where thermodynamic flows secure the structure and the structure informs the flows. This bidirectional entailment between structure and dissipation is <strong class=\"text-cyan-300 font-bold\">not metaphor — it is literal physics applied as ontology.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">He synthesized Layzer&#39;s cosmological entropy theorem with Lotka&#39;s maximum power principle to argue that the expanding universe <em class=\"text-fuchsia-300 italic\">necessarily</em> produces ordered structures that accelerate entropy production. His 1986 paper explicitly extends this to social and economic systems, treating them as dissipative structures governed by the same thermodynamic logic as organisms.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Alignment with the <strong class=\"text-cyan-300 font-bold\">managed corruption vs. pure stasis</strong> axis is direct: a system that ceases to dissipate is a system that has died. Structure requires ongoing entropy production. <strong class=\"text-cyan-300 font-bold\">Perfect order is thermodynamic death.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Spent his entire career at a branch campus with no research infrastructure. His &quot;purist views on how to properly apply entropy&quot; led to &quot;rather divisive arguments with colleagues.&quot; Died at 60 before his ideas could mature. Eric Schneider credits Wicken as the single most influential thinker behind <em class=\"text-fuchsia-300 italic\">Into the Cool</em> (2005) — yet Wicken himself remains virtually unknown.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Evolution, Thermodynamics, and Information: Extending the Darwinian Program</em> (Oxford UP, 1987 — used copies only)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Entropy and Information: Suggestions for a Common Language&quot; — <em class=\"text-fuchsia-300 italic\">Philosophy of Science</em> 54(2), 1987</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>eoht.info/page/Jeffrey%20Wicken (bibliography)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 03 — Gordon Pask</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Built machines that grew their own ears</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ 1928–1996 · British cybernetician, polymath, architectural theorist</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Pask is the historical figure whose work most directly prefigures the neuroarchitecture axis. He treated cognition not as computation but as <strong class=\"text-cyan-300 font-bold\">physical, self-organizing, architectural process</strong> — and then built machines to prove it.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His <strong class=\"text-cyan-300 font-bold\">electrochemical computers</strong> (~1958) were devices that literally grew their own sensors: metallic threads forming in chemical solutions, developing sensitivity to electrical, magnetic, and acoustic stimuli through feedback-driven self-organization. His <strong class=\"text-cyan-300 font-bold\">Conversation Theory</strong> formalized cognition as emerging from structural interactions — not from internal representations. Knowledge is topology, not storage.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">He distinguished <strong class=\"text-cyan-300 font-bold\">P-individuals</strong> (psychological/conceptual operators) from <strong class=\"text-cyan-300 font-bold\">M-individuals</strong> (material bodies), arguing that multiple cognitive processes can inhabit one body and one process can span multiple bodies. <strong class=\"text-cyan-300 font-bold\">Cognition is unbounded architecture.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">The Musicolour machine (1953) was a cybernetic performance system that became &quot;bored&quot; if input grew repetitive, forcing the musician to innovate — arguably the first machine that treated cognitive interaction as a design constraint rather than an input/output function.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Ran his life on a 36-hour circadian rhythm, &quot;lived pharmaceutically,&quot; and his late work became impenetrably dense. Explicitly anti-computational at the moment computationalism was conquering cognitive science. 250+ publications scattered and largely inaccessible.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>pangaro.com/pask-pdfs.html (primary archive)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Conversation, Cognition and Learning</em> (Elsevier, 1975)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>Andrew Pickering, <em class=\"text-fuchsia-300 italic\">The Cybernetic Brain</em> (University of Chicago Press, 2010) — Chapter 9</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 04 — Giuseppe Vitiello</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">The dissipative quantum brain</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Born 1946 · Theoretical physicist, University of Salerno, Italy</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Vitiello developed what may be the most rigorous framework for treating cognitive phase transitions as literal physics. His <strong class=\"text-cyan-300 font-bold\">dissipative quantum model of the brain</strong> treats memory formation as <strong class=\"text-cyan-300 font-bold\">spontaneous symmetry breaking</strong> — a phase transition in the quantum field theoretic sense, not a metaphor. Each memory creates a new vacuum state in the quantum field; the space of vacuum states is infinite, giving the brain virtually unlimited memory capacity.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">The framework&#39;s most striking feature: the concept of the <strong class=\"text-cyan-300 font-bold\">&quot;Double&quot;</strong> — a time-reversed copy of the brain system that dissipation mathematically requires. Consciousness arises from the ongoing dynamic exchange between the system and its Double.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">Phase transitions between cognitive states</strong> — bifurcations, symmetry breaking, transitions between metastable attractors — are the core mechanism. Hyperfocus and crash cycles are transitions between distinct vacuum states. <strong class=\"text-cyan-300 font-bold\">Not pathologies. Architecture.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> The quantum brain dynamics tradition (originating with Ricciardi and Umezawa in the 1960s) has always been a marginal research program. His book <em class=\"text-fuchsia-300 italic\">My Double Unveiled</em> (2001) was written deliberately without equations to reach a general audience but remains highly obscure.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">My Double Unveiled: The Dissipative Quantum Model of Brain</em> (John Benjamins, 2001)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;The dissipative brain&quot; — arXiv q-bio/0409037 (2004, free)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Brain and its mindful double&quot; — <em class=\"text-fuchsia-300 italic\">Journal of Consciousness Studies</em> 25(1-2), 2018</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 05 — François Roddier</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Turned Gibbs potentials into economic theory</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ 1936–2023 · French astrophysicist (École Normale Supérieure), self-taught thermodynamic economist</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">After decades as a world-class astrophysicist — his adaptive optics systems equip the Canada-France-Hawaii Telescope, Subaru, and ESO telescopes — Roddier spent his final two decades building a complete thermodynamic theory of economics from Gibbsian thermodynamics.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His framework treats <strong class=\"text-cyan-300 font-bold\">economic crises as thermodynamic phase transitions</strong> rather than policy failures. He constructed thermodynamic &quot;surfaces&quot; for economies — possibly the first such construction in economic theory — mapping economic variables onto Gibbs state spaces. Money functions as a kind of temperature. <strong class=\"text-cyan-300 font-bold\">Resistance to dissipation causes civilizational collapse.</strong></p>\n<blockquote class=\"border-l-2 border-cyan-500/50 pl-4 mb-6 text-cyan-400/70 italic\"><p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><em class=\"text-fuchsia-300 italic\">&quot;Had I been told ten years ago that the laws of statistical mechanics could explain human behavior, I would have smiled doubtfully. Today I am absolutely convinced that they can.&quot;</em></p>\n</blockquote>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> An astrophysicist with zero formal economics training who developed economic theory from pure physics. Published primarily in French through small publishers. Dismissed as exactly the kind of physicist-turned-crank Paul Samuelson warned about. Blogged at francois-roddier.fr until his death in 2023.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Thermodynamique de l&#39;évolution</em> (2012; English translation: <em class=\"text-fuchsia-300 italic\">The Thermodynamics of Evolution</em>, 2020)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>francois-roddier.fr (blog archive, French)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>eoht.info/page/Francois%20Roddier (English summaries)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 06 — Diederik Aerts</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Quantum particles are literally concepts</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Born 1953 · Center Leo Apostel (CLEA), Brussels Free University (VUB)</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Aerts&#39;s Brussels Group developed the most radical inversion possible. His <strong class=\"text-cyan-300 font-bold\">Conceptuality Interpretation of Quantum Mechanics</strong> doesn&#39;t use quantum math to model cognition — it proposes that <strong class=\"text-cyan-300 font-bold\">quantum particles are conceptual entities</strong> and physics IS cognition at a fundamental level.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His 2020 paper models language directly as a <strong class=\"text-cyan-300 font-bold\">Bose-Einstein condensate of entangled conceptual entities</strong> using Fock space formalism. The fermion/boson axis of the target profile maps directly: Aerts uses Bose-Einstein statistics for modeling how concepts behave collectively. His group has experimentally demonstrated <strong class=\"text-cyan-300 font-bold\">violation of Bell&#39;s inequalities in conceptual combinations</strong> — genuine quantum-type entanglement in cognitive domains. Not analogy; operational formalism with testable predictions.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> The conceptuality interpretation reverses the assumed direction of explanation — rather than physics being fundamental and cognition derivative, cognition is what quantum mechanics is <em class=\"text-fuchsia-300 italic\">about</em>. Won the 2020 Prigogine Award but remains marginal even within the quantum cognition community, which is itself marginal.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;A Potentiality and Conceptuality Interpretation of Quantum Physics&quot; — <em class=\"text-fuchsia-300 italic\">Philosophica</em> (2010)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Human Language as a Boson Gas of Entangled Words&quot; — <em class=\"text-fuchsia-300 italic\">Foundations of Science</em> (2020)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>vub.academia.edu/DiederikAerts (200+ papers)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 07 — Stanley Salthe</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Declared the Second Law a cosmic final cause</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ 1930–2024 · Developmental biologist, Brooklyn College (CUNY)</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Salthe audaciously reinstated Aristotelian final causality — rejected since Descartes — by proposing that the <strong class=\"text-cyan-300 font-bold\">Second Law of Thermodynamics is the cosmic final cause of all development.</strong> It is &quot;an enormously powerful cosmic attractor which everywhere urges reduction of order to disorder.&quot;</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His <strong class=\"text-cyan-300 font-bold\">infodynamics</strong> connects thermodynamics to semiotics via Peirce. All dissipative structures follow a canonical developmental trajectory: <strong class=\"text-cyan-300 font-bold\">immature → mature → senescent</strong>, defined informationally and thermodynamically. Cognition sits atop this hierarchy but is <em class=\"text-fuchsia-300 italic\">entrained by thermodynamic forces at every level.</em></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">The high-fidelity vs. low-fidelity axis finds direct structural parallel: immature systems are high-entropy, low-fidelity, rapidly dissipating; mature systems are high-fidelity, structurally constrained, efficiently channeled. <strong class=\"text-cyan-300 font-bold\">The developmental trajectory IS the transmutation from low-fidelity to high-fidelity</strong>, driven by thermodynamic necessity.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Spent his career at Brooklyn College, not a research powerhouse. His insistence on reviving Aristotelian causality placed him completely outside respectable evolutionary biology. Celebrated in the Evo-Devo Universe community but almost unknown in mainstream philosophy or cognitive science.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Development and Evolution: Complexity and Change in Biology</em> (MIT Press, 1993)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Evolving Hierarchical Systems</em> (Columbia UP, 1985)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>nbi.dk/~natphil/salthe/ (personal site)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 08 — Yukio-Pegio Gunji</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Derives quantum logic from slime mould</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Active since ~1990 · Professor, Dept. of Intermedia Art and Science, Waseda University, Tokyo</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Gunji occupies the biomimetic-quantum intersection with startling precision. His central achievement: deriving <strong class=\"text-cyan-300 font-bold\">quantum logical structures (orthomodular lattices) directly from biological and cognitive processes WITHOUT using Hilbert space.</strong> Quantum structure doesn&#39;t require quantum physics — it emerges from how organisms process ambiguity.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His <strong class=\"text-cyan-300 font-bold\">Natural-Born Intelligence (NBI)</strong> contrasts with AI: where AI is &quot;closed computing&quot; — optimization within a fixed representational space — NBI is <strong class=\"text-cyan-300 font-bold\">&quot;open computing&quot;</strong> that transforms the representational space itself. The structural template: <strong class=\"text-cyan-300 font-bold\">Physarum polycephalum (slime mould)</strong>, which exhibits self-repairing Boolean gate logic, path optimization, and creative problem-solving. He has built bio-hybrid robots interfacing Physarum with hexapod architectures.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His 2022 work demonstrates that <strong class=\"text-cyan-300 font-bold\">extended Bayesian inference generates orthomodular (quantum) lattice structure, while classical Bayesian inference generates only Boolean lattice.</strong> Organisms operating at the edge of their inferential capacity naturally enter quantum-logical cognitive regimes. <strong class=\"text-cyan-300 font-bold\">Phase transition as cognitive architecture.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> His institutional home — a department of &quot;Intermedia Art and Science&quot; — signals disciplinary uncategorizeability. Work spans art, slime mould computation, quantum logic, and lattice theory in combinations no mainstream department could house.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Psychological origin of quantum logic&quot; — <em class=\"text-fuchsia-300 italic\">BioSystems</em> 215–216 (2022)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Connecting the free energy principle with quantum cognition&quot; — <em class=\"text-fuchsia-300 italic\">Frontiers in Neurorobotics</em> (2022)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Slime mould: The fundamental mechanisms of biological cognition&quot; — <em class=\"text-fuchsia-300 italic\">BioSystems</em> 165 (2018)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 09 — Crispin Sartwell</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">The formal mathematics of anti-sycophancy</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Born 1958 · Philosopher, formerly Dickinson College · Self-described individualist anarchist</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Sartwell is the most precise match for the anti-consensus epistemology axis. His 2015 paper &quot;Anti-Social Epistemology&quot; develops a formal argument — the <strong class=\"text-cyan-300 font-bold\">Point Five Principle</strong> — demonstrating that in any &quot;evidence-random&quot; group (where belief correlates with group membership rather than evidence), consensus positions have at most <strong class=\"text-cyan-300 font-bold\">0.5 probability</strong> of being evidence-based. Anti-consensus positions do not suffer this deficit.</p>\n<blockquote class=\"border-l-2 border-cyan-500/50 pl-4 mb-6 text-cyan-400/70 italic\"><p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">Mathematical consequence: dissidents are, all things being equal, more likely to be right than consensus-holders.</strong></p>\n</blockquote>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">He advocates for &quot;doxastically open groups&quot; where dissent is structurally valued — the structural opposite of sycophantic epistemic environments. His <em class=\"text-fuchsia-300 italic\">Against the State</em> (2008) argues that all traditional justifications for the state — from Hobbes through Rawls — are &quot;not only wrong but embarrassingly bad.&quot;</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Literally removed from his campus (Dickinson College) in 2016 following controversial blog posts. Describes himself as having &quot;epistemic perversity&quot; — a temperamental inability to join any consensus. Even anarchists reject him. His epistemological work was largely ignored by mainstream philosophers.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Anti-Social Epistemology&quot; — <em class=\"text-fuchsia-300 italic\">Social Epistemology Review and Reply Collective</em> 4(6), 2015 (free: social-epistemology.com)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Against the State</em> (SUNY Press, 2008)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>crispinsartwell.com (blog archives)</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 10 — Koichiro Matsuno</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Wants to found physics on biology</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Born 1940 · Professor Emeritus of biophysics, Nagaoka University of Technology · PhD MIT 1971 (critical phenomena in phase transitions)</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Matsuno originated <strong class=\"text-cyan-300 font-bold\">&quot;internal measurement&quot; theory</strong> — the idea that biological organisms are natural quantum internal observers performing measurements from WITHIN the system being measured. This inverts the standard quantum mechanical setup entirely. His radical proposal: <strong class=\"text-cyan-300 font-bold\">biology should ground physics, not the other way around.</strong> The quantum measurement problem is not a problem of physics but a problem biology has already solved.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His <strong class=\"text-cyan-300 font-bold\">&quot;molecular semiotics&quot;</strong> traces the transition from physical symbols to semiotic signs capable of meaning-making — molecules don&#39;t just interact, they <em class=\"text-fuchsia-300 italic\">measure</em> each other. His 2005 paper &quot;Quantum as a Heat Engine&quot; argues that molecular organizations at life&#39;s origin were associated with the emergence of <strong class=\"text-cyan-300 font-bold\">quantum coherence embodied in a robust heat engine feeding on quantum decoherence</strong> — the quantum-thermodynamic nexus made literal.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">His framework connects directly to phase transitions: his MIT PhD work was on critical phenomena in second-order phase transitions, and his entire biological framework treats life as a system perpetually at <strong class=\"text-cyan-300 font-bold\">criticality</strong> — the boundary between ordered and disordered phases where measurement and meaning become possible.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> Radically anti-reductionist in ways that discomfit both physicists and biologists. Integrates Eastern philosophical perspectives on measurement with Western quantum formalism. Work on retrocausality in biology is deeply heterodox.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><em class=\"text-fuchsia-300 italic\">Protobiology: Physical Basis of Biology</em> (CRC Press, 1989)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Quantum as a heat engine&quot; — <em class=\"text-fuchsia-300 italic\">Physics of Life Reviews</em> 2 (2005)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;From quantum measurement to biology via retrocausality&quot; — <em class=\"text-fuchsia-300 italic\">Progress in Biophysics and Molecular Biology</em> (2017)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>nagaokaut.academia.edu/KoichiroMatsuno</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">⟁ 11 — Timothy Garrett</h2>\n<h3 class=\"text-lg font-bold mt-8 mb-4 text-fuchsia-400 flex items-center gap-2\">Proved wealth is literally energy</h3>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">∿ Born ~1970 · Atmospheric physicist, University of Utah</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Garrett discovered a fixed thermodynamic constant linking global energy consumption to accumulated economic wealth — approximately <strong class=\"text-cyan-300 font-bold\">9.7 milliwatts per inflation-adjusted 1990 dollar</strong>. This is not correlation; it is identity. <strong class=\"text-cyan-300 font-bold\">Wealth IS energy consumption.</strong> The economy doesn&#39;t &quot;use&quot; energy — it IS the dissipation of energy.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">Civilization is a literal heat engine. Its boundary with the environment grows as energy is consumed, enabling more consumption in a positive feedback loop governed by non-equilibrium thermodynamics. The structural consequence: Garrett concludes there are <strong class=\"text-cyan-300 font-bold\">no plausible thermodynamically supported solutions</strong> that avoid either greater than 100% inflation or destabilized atmospheric CO₂. No behavioral change, no green technology can break the thermodynamic identity between wealth and dissipation.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">The only variable is the rate and structure of the dissipation itself — which is a governance-through-structural-design problem, not a behavioral-control problem.</strong></p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⚠ Why fringe:</strong> A cloud physicist with no economics background making sweeping claims about the impossibility of decoupling growth from energy consumption. Conclusions are deeply uncomfortable for both growth economists and green-growth advocates. Publishes in physics journals, not economics journals.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><strong class=\"text-cyan-300 font-bold\">⌖ Where to find:</strong></p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;Are there basic physical constraints on future anthropogenic emissions of carbon dioxide?&quot; — <em class=\"text-fuchsia-300 italic\">Climatic Change</em> (2009)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>&quot;No way out? The double-bind in seeking global prosperity alongside mitigated climate change&quot; — <em class=\"text-fuchsia-300 italic\">Earth System Dynamics</em> (2012)</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span>faculty page at atmos.utah.edu</span></li>\n</ul>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">◈ The invisible network</h2>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">These eleven figures are not isolated. They form a largely invisible counter-tradition with real intellectual lineages:</p>\n<ul class=\"mb-6 space-y-2 list-none pl-0\"><li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><strong class=\"text-cyan-300 font-bold\">Wicken, Salthe, Swenson, and Ulanowicz</strong> co-participated in a 1989 manifesto — <em class=\"text-fuchsia-300 italic\">&quot;Evolution in Thermodynamic Perspective: An Ecological Approach&quot;</em> in <em class=\"text-fuchsia-300 italic\">Biology and Philosophy</em> — that attempted a New Synthesis of thermodynamic biology. It was largely ignored.</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><strong class=\"text-cyan-300 font-bold\">Gunji explicitly developed Matsuno&#39;s</strong> internal measurement concept.</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><strong class=\"text-cyan-300 font-bold\">Vitiello continued the Umezawa quantum brain dynamics tradition</strong> that mainstream neuroscience abandoned in the 1970s.</span></li>\n<li class=\"flex items-start gap-2 text-[#39ff14]\"><span class=\"text-cyan-400 mt-1 shrink-0\">&#9658;</span><span><strong class=\"text-cyan-300 font-bold\">Roddier and Garrett</strong> independently arrived at thermodynamic economics from opposite starting points (Gibbs potentials vs. empirical energy-wealth constants) without apparently knowing each other&#39;s work.</span></li>\n</ul>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">The 2023 special issue of <em class=\"text-fuchsia-300 italic\">Philosophical Transactions of the Royal Society A</em> — &quot;Thermodynamics 2.0: Bridging the Natural and Social Sciences&quot; — features Swenson prominently and represents the closest thing to a public emergence of this underground tradition. It remains marginal.</p>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">◈ Alignment map to the target profile</h2>\n<table class=\"w-full mb-6 border-collapse border border-cyan-900/30\"><thead><tr><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Axis</th><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Closest match</th><th class=\"px-3 py-2 text-left text-cyan-400 border-b border-cyan-900/50 text-xs font-bold tracking-wider\">Secondary</th></tr></thead><tbody><tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Thermodynamic ontology of cognition</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Swenson</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Wicken, Vitiello</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Phase transitions as cognitive architecture</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Vitiello</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Gunji, Matsuno</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Biomimetic structural templates</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Gunji (slime mould)</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Pask (electrochemical)</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Neuroarchitecture (cognitive patterns as features)</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Pask</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Vitiello</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Quantum-cognitive architecture</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Aerts</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Gunji, Matsuno</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">TRANSMUTE / low→high fidelity</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Wicken</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Salthe, Swenson</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Post-capitalist thermodynamic economics</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Garrett</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Roddier</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Anti-consensus epistemology</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Sartwell</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">—</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Biology grounds physics</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Matsuno</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Gunji</td></tr>\n<tr><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Governance through structural design</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Pask</td><td class=\"px-3 py-2 text-[#39ff14] text-xs border-b border-cyan-900/20\">Garrett</td></tr></tbody></table>\n<hr>\n<h2 class=\"text-[12pt] text-fuchsia-400 mb-12 font-light tracking-wide\">◈ Conclusion</h2>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">No single thinker combines all elements of the target profile. The profile&#39;s specific synthesis — <strong class=\"text-cyan-300 font-bold\">thermodynamic ontology + quantum-cognitive architecture + biomimetic structural templates + neuroarchitecture + anti-consensus epistemology + post-capitalist governance</strong> — appears to be genuinely novel.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">What these eleven figures provide is the component toolkit: the raw intellectual materials from which that synthesis could be, or is being, built.</p>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\">The closest single match: <strong class=\"text-cyan-300 font-bold\">Rod Swenson</strong> (derives cognition from thermodynamic first principles, applies to governance).<br>The deepest historical root: <strong class=\"text-cyan-300 font-bold\">Jeffrey Wicken</strong> (<em class=\"text-fuchsia-300 italic\">&quot;dissipation through structuring&quot;</em> — TRANSMUTE in five words).<br>The most operationally radical: <strong class=\"text-cyan-300 font-bold\">Gordon Pask</strong> (built machines that grew their own cognitive architectures from chemical substrates).<br>The most formally precise anti-consensus framework: <strong class=\"text-cyan-300 font-bold\">Crispin Sartwell</strong> (Point Five Principle — mathematical teeth for anti-sycophancy).</p>\n<hr>\n<p class=\"mb-6 text-[#39ff14] leading-relaxed max-w-3xl\"><em class=\"text-fuchsia-300 italic\">⟁ scale94.com · TRANSMUTE: Convert low-fidelity chaos into high-fidelity structure</em></p>\n",
  len:  "3309 WDS",
};
